window.kbPageData["views/entry/k-5dc6f7bab5ea7821"] = {"key":"entry/k-5dc6f7bab5ea7821","state":{"route":"entry/k-5dc6f7bab5ea7821"},"node":{"id":"k-5dc6f7bab5ea7821","mode":"k","title":"相似立体的体积比","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["相似立体的体积比等于线性相似比的立方","相似立体的体积比等于相似比的立方","相似立体的体积比等于对应长度比的立方"],"qs":["国考 2023 副省级 行测#75","国考 2025 副省级 行测#80","国考 2025 地市级 行测#75"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":2,"repeatPositions":1,"directorySummary":"两个立体几何图形相似时，体积比等于对应长度之比的立方。","review":{"definition":"两个立体几何图形相似时，体积比等于对应长度之比的立方。","explanation":"液面尚在倒立圆锥段内时，水体与整个圆锥共顶点，液面平行于圆锥底面，两者是相似圆锥。1分钟时水深6厘米，是锥高12厘米的一半，所以此时水量是整个锥段容积的1/8。按恒定流量注水，锥段从空到满共需8分钟。","references":[],"evidence":"在立体几何中，体积比等于相似比的立方","disposition":"独立词条","basis":"据原题和解析编释。","title":"相似立体的体积比","related":[],"examFocus":{"国考 2023 副省级 行测#75":"用漂浮平衡比较圆锥在两种液体中的浸没体积，再用相似圆锥的体积比联系尖部朝上时的露出高度。","国考 2025 副省级 行测#80":"用相似圆锥的体积比把初始水深换成水量，再根据恒定流量区分锥段和柱段的注水时间。"}},"readings":[{"origin":"k-5dc6f7bab5ea7821","title":"相似立体的体积比","qs":["国考 2025 地市级 行测#75"],"definition":"两个立体几何图形相似时，体积比等于对应长度之比的立方。","explanation":"液面尚在倒立圆锥段内时，水体与整个圆锥共顶点，液面平行于圆锥底面，两者是相似圆锥。1分钟时水深6厘米，是锥高12厘米的一半，所以此时水量是整个锥段容积的1/8。按恒定流量注水，锥段从空到满共需8分钟。","evidence":"在立体几何中，体积比等于相似比的立方","doubt":"","references":[]},{"origin":"k-7bd0239dc6dddb58","title":"相似立体的体积比","qs":["国考 2025 副省级 行测#80"],"definition":"两个相似立体的体积比等于对应长度之比的立方。","explanation":"注水1分钟后，水在倒立圆锥内形成高6厘米的小圆锥，与高12厘米的整个圆锥相似。高度比为1∶2，体积比即为1∶8。匀速注水时，注入体积与用时成正比，因此注满圆锥共需8分钟，余下23分钟用于注满圆柱。圆锥与圆柱底面积相等，而圆锥体积等于底面积乘高的三分之一，所以圆柱高为(12÷3)×(23÷8)=11.5厘米，容器总高23.5厘米，选D。","evidence":"体积比等于相似比的立方","doubt":"","references":[]},{"origin":"k-8f4f2cb30a136f36","title":"相似立体的体积比","qs":["国考 2023 副省级 行测#75"],"definition":"两个相似立体的体积比等于对应长度之比的立方。已知体积比时，可开立方求对应长度之比。","explanation":"题设圆锥轴线竖直，液面与底面平行，液面截出的带尖部分与整个圆锥相似。尖部朝下时，液面下的小圆锥高为0.9x，体积占0.9³＝0.729。按两种液体的密度和漂浮平衡换算，尖部朝上时浸没体积占0.486，露出的小圆锥体积占0.514。由于0.514大于0.8³＝0.512，露出高度超过0.8x，对应A项。","evidence":"其与实心圆锥零件整体相似","doubt":"","references":[]}]},"questions":{"国考 2023 副省级 行测#75":{"paper":"国考 2023 副省级 行测","n":75,"mod":"数量关系","src":["503793642e845de9795f.pdf",13],"asrc":["ecade1ff5af69283232e.pdf",22],"card":"29ff74f14f6c672d4875465e","links":[{"id":"k-5dc6f7bab5ea7821","role":"解题依据","why":"液面截得的小圆锥与整个圆锥相似，可在高度比和体积比之间换算。"}]},"国考 2025 副省级 行测#80":{"paper":"国考 2025 副省级 行测","n":80,"mod":"数量关系","src":["ffe12c35a46d4df574ec.pdf",13],"asrc":["ff0b352b44d417525086.pdf",25],"card":"4cb7ccaec7cc18717d3226f7","links":[{"id":"k-5dc6f7bab5ea7821","role":"解题依据","why":"圆锥段内的水体与整个圆锥相似，可由高度比确定体积比。"}]},"国考 2025 地市级 行测#75":{"paper":"国考 2025 地市级 行测","n":75,"mod":"数量关系","src":["31f401e91aef8d11365d.pdf",13],"asrc":["8cece062c7c079b53130.pdf",23],"card":"63d35350d33b8f087aa1e199","links":[{"id":"k-5dc6f7bab5ea7821","role":"直接考查","why":"锥段内的水体与整个圆锥相似，可由水深与锥高之比确定体积比。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-5dc6f7bab5ea7821":[["国考 2023 副省级 行测#75"],["国考 2025 副省级 行测#80","国考 2025 地市级 行测#75"]]}};
